using System.Reflection;

namespace Storiva.App.Icons;

/// <summary>Storiva's own application icon (generated by tools/generate-brand-icon.ps1).</summary>
internal static class BrandIcon
{
    private const string Resource = "Storiva.Brand.storiva.ico";

    /// <summary>New <see cref="Icon"/> instance; the caller owns it.</summary>
    public static Icon Create()
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(Resource)
            ?? throw new InvalidOperationException($"Embedded resource '{Resource}' is missing.");
        return new Icon(stream);
    }

    /// <summary>Bitmap of the closest icon entry, scaled to <paramref name="size"/> pixels.</summary>
    public static Bitmap Bitmap(int size)
    {
        using var stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(Resource)
            ?? throw new InvalidOperationException($"Embedded resource '{Resource}' is missing.");
        using var icon = new Icon(stream, size, size);
        return icon.ToBitmap();
    }
}
